{
  "packs": [
    {
      "id": "basics",
      "version": "60924.1"
    },
    {
      "id": "claudinite-lifecycle",
      "version": "60924.1"
    },
    {
      "id": "git-github",
      "version": "60922.5",
      "via": [
        "basics"
      ]
    },
    {
      "id": "html",
      "version": "60921.1"
    },
    {
      "id": "claudinite-growth",
      "version": "60924.1",
      "config": {
        "retention_days": 10
      }
    },
    "local/edfringe-now",
    {
      "id": "executable-requirements",
      "version": "60922.1",
      "config": {
        "spec": "product/requirements.md"
      },
      "answers": {
        "ui_testing": "Headless Chromium via Playwright (pre-installed in the environment): render the real single-page app — Leaflet map included, with map tiles and other network faked deterministically — and assert pixel-exact visual goldens the owner reviews by sight; short per-leaf tests drive to a state and capture. Pure planner rules (plan/lib) stay node --test logic leaves. No visual harness exists yet — this is the target mechanism.",
        "requirements_source": "Authored fresh at product/requirements.md (config.spec), distilled from the existing product brief docs/product-spec.md. No prior formal requirements doc or issue-tracker backlog to extract."
      }
    },
    {
      "id": "spec-driven-product",
      "version": "60922.2"
    },
    {
      "id": "product-wiki",
      "version": "60922.3",
      "answers": {
        "product": "Fringe Discover: a spontaneity/reachability tool for the Edinburgh Festival Fringe. Where listings apps answer 'what exists?', this answers 'what can I actually make right now?' — given the user's location, how far they'll travel and how, and their next commitment, it collapses ~3,800 shows into a short list of genuinely reachable options that haven't started and still leave time to reach whatever is next.",
        "users": "Fringe-goers mid-festival, usually on foot and without a fixed plan — visitors with a gap between a booked show and dinner, locals and tourists intimidated by the programme's scale. Decisive in the moment rather than researchers: they want a short list of good, reachable options, not 3,800 search results. Emotional target: 'delight + relief'.",
        "market": "Edinburgh Fringe discovery and planning tools. Alternatives: the official Fringe app (a 'Nearby now' + shake-to-search finder), Plan My Fringe (a schedule optimiser with a walking-time 'Fringe Trail'), the edfringe.com programme and filters, the Half Price Hut (same-day discounts), review outlets such as ThreeWeeks, plus street posters and word-of-mouth. None centres full reachability — travel mode plus next-commitment slack — the way Fringe Discover does."
      }
    },
    {
      "id": "claude-code-web-users-support",
      "version": "60924.1",
      "config": {
        "repo": "missingbulb/Shepherd"
      },
      "answers": {
        "store": "missingbulb/Shepherd"
      }
    },
    {
      "id": "claudinite-tasks",
      "version": "60923.3"
    },
    {
      "id": "cloudflare-site",
      "version": "60922.2"
    },
    {
      "id": "public-website",
      "version": "60921.1"
    }
  ],
  "accept": [
    {
      "rule": "file-placement",
      "path": "product/requirements/",
      "reason": "the executable-requirements layout is a framework contract: cases live in <kind>/cases/ and the harness in shared/, so every case's reach to shared/ and to the shipped modules under js/, plan/ and shared/ is fixed by the pack's layout standard, not a placement choice"
    },
    {
      "rule": "claudinite-isolation",
      "path": "scripts/verify.sh",
      "reason": "the repo's one verification gate invokes the world sweep (engine/checks/check_the_world.mjs) so that passing it locally means what passing CI means — a commit that passed verify and went red on CI for a blocking conformance finding is what prompted this. Not the coupling the rule guards against: no canon internals are imported and nothing is inlined, it is the same documented CLI entry point .github/workflows/ already spells under the rule's own carve-out. A canon rename of that one path breaks the workflow and this script identically, and the fix is the same one line"
    }
  ],
  "taskScheduler": {
    "disabledTasks": [
      "edfringe/refresh-shows",
      "edfringe/refresh-tickets"
    ],
    "agenticTaskInvocationEndpoints": {
      "default": {
        "url": "[REDACTED:env:SESSION_INGRESS_URL]/v1/claude_code/routines/trig_019ysxedonGvJiDzVZbJamBd/fire",
        "tokenSecret": "CCR_ROUTINE_TOKEN"
      }
    }
  },

